with q as (select * from (values
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-titling-07','Lei nº 3.228/2017 — adicional de titulação','Conforme o art. 6º da Lei nº 3.228/2017, qual percentual corresponde ao título de mestrado para fins de adicional de titulação?','(A) 5%.\n(B) 7,5%.\n(C) 10%.\n(D) 15%.\n(E) 20%.','D','O art. 6º estabelece 7,5% para especialização lato sensu com pelo menos 360 horas, 15% para mestrado e 20% para doutorado, observado o limite máximo de 20%.'),
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-instruction-08','Lei nº 2.250/2009 — gratificação de instrução','A gratificação de instrução prevista no art. 31-A da Lei nº 2.250/2009 é devida ao policial civil quando:','(A) Trabalha em qualquer curso particular, sem autorização.\n(B) Exerce magistério em curso de formação ou aperfeiçoamento enquadrado na norma, observadas as condições legais.\n(C) Participa como aluno de curso de formação.\n(D) Realiza qualquer palestra fora do serviço público.\n(E) É designado para qualquer reunião administrativa.','B','O art. 31-A, incluído pela LC nº 279/2014, prevê pagamento por aula ao integrante da carreira que exerce magistério em cursos de formação/aperfeiçoamento indicados na lei, com condições específicas.'),
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-sixth-part-09','Lei nº 3.228/2017 — sexta-parte','Segundo a Lei nº 3.228/2017, como deve ser apurada a gratificação de sexta-parte?','(A) Sempre corresponde a 20% do vencimento básico.\n(B) É calculada conforme o art. 36, § 4º, da Constituição Estadual e o Estatuto dos Servidores.\n(C) É calculada pelo art. 31-A da Lei nº 2.250/2009.\n(D) Corresponde a uma remuneração extra por ano.\n(E) É automática para todo servidor desde a posse.','B','A Lei nº 3.228/2017 remete o cálculo da sexta-parte ao art. 36, § 4º, da Constituição Estadual e ao Estatuto dos Servidores. A questão não autoriza presumir fórmula ou requisito temporal além da norma remetida.')
) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation))
